"""Frame-freedom deltas: canonical transformation generated by W = P_a h_b h_c changes T3, V2, G2 in the continuum reference."""
import pickle, itertools, sympy as sp
from cont2d import *
from match2d import sympy_terms2
from refs2d import fmap
pieces = pickle.load(open('cont2d_pieces.pkl', 'rb'))
V1, T2 = pieces['V1'], pieces['T2']
G1gen = degpart(sp.expand(lie_G((XIx, XIy))), 1)
hs = FIELDS_H
DELTAS = []   # list of dicts {'T3': terms, 'V2': terms, 'G2': terms, 'label': ...}
for a in range(4):
    for (b, c) in itertools.combinations_with_replacement(range(4), 2):
        W = FIELDS_P[a] * hs[b] * hs[c]
        dT3 = sp.expand(PB(N * T2, W))
        dV2 = sp.expand(PB(N * K * V1, W))
        dG2 = sp.expand(PB(G1gen, W))
        DELTAS.append(dict(label=(a, b, c),
                           T3=sympy_terms2(dT3, fmap, x, y) if dT3 != 0 else [],
                           V2=sympy_terms2(dV2, fmap, x, y) if dV2 != 0 else [],
                           G2=sympy_terms2(dG2, fmap, x, y) if dG2 != 0 else []))
if __name__ == '__main__':
    print(len(DELTAS), [ (d['label'], len(d['T3']), len(d['V2']), len(d['G2'])) for d in DELTAS[:6]])
